}
  if (!isNaN(eventDate)) {
    if (this_sel.find('.years').length > 0) {
      this_sel.find('.years').text(years);
  }
  if (this_sel.find('.days').length > 0) {
    this_sel.find('.days').text(days);
  }
  if (this_sel.find('.month').length > 0) {
